            Console.WriteLine("MY_FLAG not set, using default");
        }
    }
}

arguments.new_str:
class EnvVarCheck
{
    void CheckFlag()
    {
        // On Linux, set via: export MY_FLAG=""
        // .NET 9: empty env vars are no longer treated as unset,
        // so GetEnvironmentVariable("MY_FLAG") now returns "" instead of null.
        // Use IDictionary.Contains to distinguish "not set" from "set to empty".
        var envVars = Environment.GetEnvironmentVariables();
        if (!envVars.Contains("MY_FLAG"))
        {
            Console.WriteLine("MY_FLAG not set, using default");
        }
    }
}

